#include "stdafx.h"#include "HcdElementBase.h"struct SCMPR_P{#include "PrivateVars/CMPR.h"};class KCMPR : public KHcdElementBase  , protected SCMPR_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _CMPR("CMPR", KCMPR::Create);IHcdElement *KCMPR::Create(){  return new KCMPR;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KCMPR, 5 )void KCMPR::InitParm(){#include "PrivateVars/CMPR.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KCMPR::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KCMPR::StepCalc( SStepCalcParams &params ){  XGY = X > Y ? 1 : 0;  XEY = X == Y ? 1 : 0;  XLY = X < Y ? 1 : 0;}